import{_ as n,o,c as s,ah as t}from"./chunks/framework.Yx0DUrwu.js";const m=JSON.parse('{"title":"生物学知识","description":"","frontmatter":{},"headers":[],"relativePath":"biology/index.md","filePath":"biology/index.md","lastUpdated":1787830595000}'),e={name:"biology/index.md"};function r(i,a,p,g,l,d){return o(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="生物学知识" tabindex="-1">生物学知识 <a class="header-anchor" href="#生物学知识" aria-label="Permalink to &quot;生物学知识&quot;">​</a></h1><p>这一部分先按“分子信息流 -&gt; 多组学层级 -&gt; 测序技术 -&gt; 细胞类型 -&gt; 免疫学机制 -&gt; 组织微环境”的顺序组织。单细胞分析的难点不只是跑工具，而是把细胞群、标志基因、通路、细胞状态和疾病机制放回生物学框架里解释。</p><div class="path-grid"><a href="/biology/central-dogma-omics"><strong>中心法则与组学层级</strong><span>从 DNA、RNA、蛋白质到代谢物，再扩展到微生物群落和多组学整合。</span></a><a href="/biology/sequencing-principles"><strong>测序方法与技术原理</strong><span>理解不同测序方法的读出对象、实验偏倚和适合回答的问题。</span></a><a href="/biology/common-cell-types"><strong>常见细胞类型</strong><span>按细胞谱系整理功能、典型标志基因和注释时的常见注意事项。</span></a><a href="/biology/immunology-microenvironment"><strong>免疫系统与微环境</strong><span>免疫细胞谱系、先天/适应性免疫、肿瘤和组织微环境解释框架。</span></a><a href="/biology/immunology-roadmap"><strong>Janeway 免疫学学习图谱</strong><span>把《詹韦免疫生物学》的五大部分重组为适合单细胞研究的免疫学路线。</span></a><a href="/biology/innate-immunity"><strong>固有免疫</strong><span>屏障、补体、模式识别、炎症、干扰素、NK 细胞和固有淋巴样细胞。</span></a><a href="/biology/antigen-recognition-presentation"><strong>抗原识别与抗原提呈</strong><span>BCR、TCR、MHC、抗原加工、交叉提呈和非经典抗原识别。</span></a><a href="/biology/lymphocyte-development-activation"><strong>淋巴细胞发育与活化</strong><span>V(D)J 重排、B/T 细胞选择、TCR/BCR 信号、共刺激和共抑制。</span></a><a href="/biology/adaptive-effector-immunity"><strong>适应性免疫应答</strong><span>T 细胞启动、CD4/CD8 效应分化、B 细胞生发中心、抗体功能和免疫记忆。</span></a><a href="/biology/mucosal-disease-immunotherapy"><strong>黏膜免疫、疾病与治疗</strong><span>黏膜屏障、微生物群、免疫缺陷、过敏、自身免疫、移植、疫苗和肿瘤免疫治疗。</span></a><a href="/references/"><strong>参考资料</strong><span>收集本部分引用的经典论文、高质量综述和官方资源。</span></a></div><h2 id="阅读方式" tabindex="-1">阅读方式 <a class="header-anchor" href="#阅读方式" aria-label="Permalink to &quot;阅读方式&quot;">​</a></h2><div class="flow-strip"><span>先问分子层级</span><span>再问测量技术</span><span>接着看细胞类型</span><span>再看免疫识别</span><span>理解效应应答</span><span>最后回到组织生态位</span></div><div class="doc-callout important"><strong>为什么先放文献背书</strong><p>单细胞结论很容易被图形直觉带偏。这里优先引用经典论文、高影响力综述和技术方法论文，是为了让每个概念都能回到可靠出处。</p></div>',6)])])}const h=n(e,[["render",r]]);export{m as __pageData,h as default};
